#!/usr/bin/env node

import { GetNotesMCPServer } from './server.js';
import { config } from './config/index.js';
import { logger } from './utils/logger.js';

// 解析命令行参数
function parseArgs() {
  const args = process.argv.slice(2);
  const options = {
    transport: 'stdio', // 默认使用stdio模式
    port: 3000,
    host: 'localhost'
  };
  
  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--transport':
      case '-t':
        options.transport = args[++i];
        break;
      case '--port':
      case '-p':
        options.port = parseInt(args[++i]) || 3000;
        break;
      case '--host':
      case '-h':
        options.host = args[++i] || 'localhost';
        break;
      case '--help':
        printHelp();
        process.exit(0);
        break;
      default:
        logger.warn(`Unknown argument: ${args[i]}`);
    }
  }
  
  return options;
}

function printHelp() {
  console.log(`
${config.server.name} v${config.server.version}

Usage: node src/index.js [options]

Options:
  -t, --transport <type>   Transport mode: stdio|sse|http (default: stdio)
  -p, --port <number>      Port for HTTP/SSE transport (default: 3000)
  -h, --host <hostname>    Host for HTTP/SSE transport (default: localhost)
  --help                   Show this help message

Examples:
  # STDIO mode (default)
  node src/index.js
  
  # SSE mode
  node src/index.js --transport sse --port 3000
  
  # HTTP mode
  node src/index.js --transport http --port 8080 --host 0.0.0.0

Environment Variables:
  GET_NOTE_API_KEY (required) - Your Get Notes API key
  GET_NOTE_API_BASE_URL (optional) - API base URL override
  GET_NOTE_API_TIMEOUT (optional) - Request timeout in ms
  GET_NOTE_API_RETRIES (optional) - Number of retry attempts
  LOG_LEVEL (optional) - Logging level (debug|info|warn|error)
`);
}

// 主函数
async function main() {
  try {
    const options = parseArgs();
    
    logger.info(`Starting ${config.server.name} v${config.server.version}`);
    logger.info(`Transport: ${options.transport}`);
    
    if (options.transport !== 'stdio') {
      logger.info(`Endpoint: ${options.host}:${options.port}`);
    }
    
    const server = new GetNotesMCPServer(options);
    await server.start();
    
  } catch (error) {
    logger.error('Fatal error:', error);
    process.exit(1);
  }
}

// 运行服务器
if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((error) => {
    logger.error('Unhandled error:', error);
    process.exit(1);
  });
}